import{_ as o,o as a,c as t,a3 as n}from"./chunks/framework.DACwFHq9.js";const m=JSON.parse(`{"title":"AI & MCP Overview","description":"Learn about Notely's local-first AI platform, embedded Model Context Protocol (MCP) server, SQLite Knowledge Graph, and ONNX vector embeddings.","frontmatter":{"title":"AI & MCP Overview","description":"Learn about Notely's local-first AI platform, embedded Model Context Protocol (MCP) server, SQLite Knowledge Graph, and ONNX vector embeddings.","keywords":"ai, mcp, model context protocol, claude desktop, cursor, antigravity, vector database, knowledge graph, bge embeddings","category":"AI"},"headers":[],"relativePath":"ai/index.md","filePath":"ai/index.md","lastUpdated":1789752683000}`),r={name:"ai/index.md"};function i(d,e,s,l,c,p){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-mcp-subsystem-overview" tabindex="-1">AI &amp; MCP Subsystem Overview <a class="header-anchor" href="#ai-mcp-subsystem-overview" aria-label="Permalink to &quot;AI &amp; MCP Subsystem Overview&quot;">​</a></h1><p>Notely features a modular, local-first AI platform designed around private data control. Markdown files remain the absolute source of truth, parsed and indexed into offline-first SQLite databases to fuel semantic search, knowledge discovery, and external agent integrations via Model Context Protocol (MCP).</p><hr><h2 id="capabilities-at-a-glance" tabindex="-1">Capabilities at a Glance <a class="header-anchor" href="#capabilities-at-a-glance" aria-label="Permalink to &quot;Capabilities at a Glance&quot;">​</a></h2><h3 id="_1-embedded-model-context-protocol-mcp-server" tabindex="-1">1. Embedded Model Context Protocol (MCP) Server <a class="header-anchor" href="#_1-embedded-model-context-protocol-mcp-server" aria-label="Permalink to &quot;1. Embedded Model Context Protocol (MCP) Server&quot;">​</a></h3><ul><li>Runs a dual-transport (Streamable HTTP and SSE) MCP server on <code>http://127.0.0.1:3700</code>.</li><li>Connects external AI assistants (Google Antigravity, Claude Desktop, Cursor, and IDE agents) directly to workspace notes, tasks, and diagrams.</li><li>Exposes <strong>7 high-signal enterprise tools</strong> (<code>search</code>, <code>read_note</code>, <code>edit_note</code>, <code>manage_tasks</code>, <code>manage_diagrams</code>, <code>workspace_overview</code>, <code>git_control</code>) with atomic write safety and dry-run options.</li><li>Exposes <strong>5 standard MCP prompts</strong> (<code>summarize_note</code>, <code>plan_tasks</code>, <code>explore_knowledge_graph</code>, <code>refactor_note</code>, <code>daily_review</code>).</li></ul><h3 id="_2-sqlite-knowledge-graph-engine" tabindex="-1">2. SQLite Knowledge Graph Engine <a class="header-anchor" href="#_2-sqlite-knowledge-graph-engine" aria-label="Permalink to &quot;2. SQLite Knowledge Graph Engine&quot;">​</a></h3><ul><li>Extracts conceptual entities and typed relationships from Markdown documents using an offline <code>gliner2-multi-v1-onnx</code> neural model.</li><li>Outbound relations, tags, and CTE traversals are mapped into <code>{workspace}/.notes-app/ai-graph.db</code>.</li><li>Explore notes and entity clusters interactively via <strong>Workspace → Workspace Graph</strong> (<code>Ctrl/Cmd + Shift + G</code>).</li></ul><h3 id="_3-local-vector-embedding-indexer" tabindex="-1">3. Local Vector Embedding Indexer <a class="header-anchor" href="#_3-local-vector-embedding-indexer" aria-label="Permalink to &quot;3. Local Vector Embedding Indexer&quot;">​</a></h3><ul><li>High-performance vector database (<code>{workspace}/.notes-app/ai-embeddings.db</code>) storing note chunk vectors.</li><li>Runs entirely offline using a local ONNX runtime for <code>BGE-small-en-v1.5</code> 384-dimensional dense vectors, with optional fallback to cloud embedding APIs.</li><li>Background worker process handles queue processing and debounced note indexing to prevent UI thread latency.</li></ul><h3 id="_4-in-app-tools-catalog-mcp-diagnostics" tabindex="-1">4. In-App Tools Catalog &amp; MCP Diagnostics <a class="header-anchor" href="#_4-in-app-tools-catalog-mcp-diagnostics" aria-label="Permalink to &quot;4. In-App Tools Catalog &amp; MCP Diagnostics&quot;">​</a></h3><ul><li><strong>MCP Tools Page</strong> (<code>Ctrl/Cmd + Shift + M</code>): Interactive catalog to view tool definitions, test inputs, and verify outputs.</li><li><strong>AI Health / Diagnostics</strong>: Real-time telemetry dashboard monitoring MCP connection status, client sessions, request volume, and error diagnostics.</li><li><strong>AI Settings</strong> (<code>Ctrl/Cmd + Shift + ,</code>): Configure API providers, embedding options, and Knowledge Graph extraction confidence thresholds.</li></ul>',12)])])}const u=o(r,[["render",i]]);export{m as __pageData,u as default};
